import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"শিক্ষা নিশ্চয়তা আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/43-教育保障法.md","filePath":"bn/43-教育保障法.md","lastUpdated":1789183869000}'),e={name:"bn/43-教育保障法.md"};function i(o,t,h,n,s,_){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="শিক্ষা-নিশ্চয়তা-আইন" tabindex="-1">শিক্ষা নিশ্চয়তা আইন <a class="header-anchor" href="#শিক্ষা-নিশ্চয়তা-আইন" aria-label="Permalink to &quot;শিক্ষা নিশ্চয়তা আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>43</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>শিক্ষা অধিকার, সিম্বায়োসিস শিক্ষা, সাধনা বংশগতি, আজীবন শিক্ষা, শিক্ষার ন্যায়বিচার</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《শিক্ষা নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার পাঁচটি সহায়ক আইনের একটি, এবং এর উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ভেতরে সমস্ত জীবের শিক্ষা অধিকার নিশ্চিত করা, &quot;সিম্বায়োসিস বিবর্তন&quot; কে মূল দর্শন হিসেবে শিক্ষা ব্যবস্থা স্থাপন করা, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য জ্ঞান এবং মানব সম্পদ সহায়তা প্রদান করা।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>শিক্ষার ন্যায়বিচার নীতি</td><td>সমস্ত জীব প্রজাতি, সাধনার স্তর, উত্স নির্বিশেষে, সমান শিক্ষার সুযোগ পায়</td></tr><tr><td>প্রতিভা অনুযায়ী শিক্ষা নীতি</td><td>প্রতিটি জীবের প্রতিভার পার্থক্য এবং বিবর্তনের পথের পছন্দকে সম্মান করা, ব্যক্তিগতকৃত শিক্ষা পরিকল্পনা প্রদান করা</td></tr><tr><td>জ্ঞান এবং কর্ম একীভূত নীতি</td><td>তাত্ত্বিক জ্ঞান এবং বাস্তব সাধনা একত্রিত করা, বাস্তবতা থেকে বিচ্ছিন্ন খালি কথার শিক্ষার বিরোধিতা করা</td></tr><tr><td>উন্মুক্ত এবং শেয়ার করা নীতি</td><td>শিক্ষা সম্পদ সমগ্র সমাজের জন্য উন্মুক্ত, তিনশত সেট মূল সাধনা ব্যবস্থার মৌলিক পদ্ধতি বিনামূল্যে শেখানো হয়</td></tr><tr><td>আজীবন শিক্ষা নীতি</td><td>শিক্ষা জীবনের সম্পূর্ণ প্রক্রিয়া জুড়ে চলে, প্রতিটি পর্যায়ের ক্রমাগত শিক্ষা এবং ক্ষমতা বৃদ্ধিকে সহায়তা করা</td></tr><tr><td>সাংস্কৃতিক বৈচিত্র্য নীতি</td><td>প্রতিটি প্রজাতির সাংস্কৃতিক ঐতিহ্যকে সম্মান করা, বহু-সাংস্কৃতিক বিনিময় এবং পারস্পরিক শিক্ষাকে উৎসাহিত করা</td></tr></tbody></table><h2 id="_2-শিক্ষা-অধিকারের-আইনি-নিশ্চয়তা" tabindex="-1">2. শিক্ষা অধিকারের আইনি নিশ্চয়তা <a class="header-anchor" href="#_2-শিক্ষা-অধিকারের-আইনি-নিশ্চয়তা" aria-label="Permalink to &quot;2. শিক্ষা অধিকারের আইনি নিশ্চয়তা&quot;">​</a></h2><p>এই আইন স্পষ্টভাবে নির্ধারণ করে যে, শিক্ষা অধিকার হল সিম্বায়োসিস সংবিধান দ্বারা প্রতিটি জীবকে প্রদত্ত মৌলিক অধিকার, এবং রাষ্ট্র ও সভ্যতার এই অধিকারের বাস্তবায়ন নিশ্চিত করার বাধ্যতা রয়েছে:</p><ol><li><strong>বিনামূল্যে মৌলিক শিক্ষা</strong>: সমস্ত জীব বিনামূল্যে মৌলিক শিক্ষা গ্রহণ করার অধিকার রাখে, যার মধ্যে সাধারণ জ্ঞান, মৌলিক সাধনা পদ্ধতি, সিম্বায়োসিস সভ্যতার দর্শন ইত্যাদি বিষয়বস্তু অন্তর্ভুক্ত, শিক্ষাকাল ছয় থেকে বারো বছর, এবং প্রজাতির বিকাশ চক্র অনুযায়ী সামঞ্জস্য করা হয়।</li><li><strong>বিনামূল্যে সাধনা প্রবেশ</strong>: তিনশত সেট মহাবিশ্বের মূল সাধনা ব্যবস্থার মৌলিক পদ্ধতি সমস্ত জীবের জন্য বিনামূল্যে উন্মুক্ত, এবং কোনো সংস্থা বা ব্যক্তি মৌলিক সাধনা পদ্ধতিকে ব্যক্তিগত সম্পত্তি হিসেবে দখল করে এবং ফি নিয়ে শেখাতে পারবে না।</li><li><strong>উচ্চশিক্ষার সুযোগের সমতা</strong>: সকল স্তরের শিক্ষা প্রতিষ্ঠান ভর্তিতে প্রজাতি, সাধনার স্তর, উত্স ইত্যাদি বৈষম্যমূলক শর্ত স্থাপন করতে পারবে না, এবং ভর্তির মানদণ্ড খোলা ও স্বচথ হবে।</li><li><strong>বিশেষ শিক্ষা নিশ্চয়তা</strong>: প্রতিবন্ধী জীব, বিদেশী জীব, দূরবর্তী位面 জীব ইত্যাদি গোষ্ঠীর জন্য মানানসই বিশেষ শিক্ষা সম্পদ এবং দূরবর্তী শিক্ষা সহায়তা প্রদান করা।</li><li><strong>শিক্ষা ত্রাণ ব্যবস্থা</strong>: আর্থিক কষ্টে পড়া শিক্ষার্থীদের জন্য শিক্ষা বৃত্তি, মেধা বৃত্তি এবং সুদ-বিহীন ঋণ প্রদান করা, এবং আর্থিক কারণে শিক্ষার সুযোগ হারানো নিশ্চিত না করা।</li></ol><h2 id="_3-শিক্ষা-ব্যবস্থার-কাঠামো" tabindex="-1">3. শিক্ষা ব্যবস্থার কাঠামো <a class="header-anchor" href="#_3-শিক্ষা-ব্যবস্থার-কাঠামো" aria-label="Permalink to &quot;3. শিক্ষা ব্যবস্থার কাঠামো&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতার শিক্ষা ব্যবস্থা চারটি স্তরে বিভক্ত, এবং প্রতিটি স্তরের মধ্যে জৈবভাবে সংযুক্ত:</p><table tabindex="0"><thead><tr><th>স্তর</th><th>নাম</th><th>লক্ষ্য</th><th>শিক্ষাকাল</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>প্রারম্ভিক শিক্ষা</td><td>মৌলিক জ্ঞান ক্ষমতা এবং সিম্বায়োসিস চেতনা গড়ে তোলা, মৌলিক সাধনা পদ্ধতি শেখানো</td><td>3-6 বছর</td></tr><tr><td>দ্বিতীয় স্তর</td><td>মৌলিক শিক্ষা</td><td>সাধারণ জ্ঞান এবং সাধনা তত্ত্বের পদ্ধতিগত শিক্ষা, ব্যক্তিগত প্রতিভার দিক আবিষ্কার</td><td>6-9 বছর</td></tr><tr><td>তৃতীয় স্তর</td><td>পেশাদার শিক্ষা</td><td>নির্বাচিত সাধনা ব্যবস্থা বা পেশাদার ক্ষেত্রে গভীর শিক্ষা এবং অনুশীলন</td><td>3-10 বছর</td></tr><tr><td>চতুর্থ স্তর</td><td>উচ্চস্তরের গবেষণা</td><td>উচ্চস্তরের সাধক এবং গবেষকদের জন্য অগ্রগামী অন্বেষণ এবং উদ্ভাবনী গবেষণা</td><td>সীমাহীন</td></tr></tbody></table><p>এছাড়াও, &quot;গুরু নেটওয়ার্ক ব্যবস্থা&quot; স্থাপন করা হয়েছে: নির্দিষ্ট সাধনার স্তরে পৌঁছানো সাধকদের ক্ষমতার সীমার মধ্যে প্রাথমিক সাধকদের নির্দেশনা দেওয়ার বাধ্যতা রয়েছে, এবং নির্দেশনার অবদান যৌথ উৎপাদন চুক্তি ব্যবস্থার অবদানের পরিমাণে গণনা করা হয়, এবং সংশ্লিষ্ট সম্পদ বণ্টন উপভোগ করে।</p><h2 id="_4-শিক্ষা-প্রতিষ্ঠান-এবং-শিক্ষক" tabindex="-1">4. শিক্ষা প্রতিষ্ঠান এবং শিক্ষক <a class="header-anchor" href="#_4-শিক্ষা-প্রতিষ্ঠান-এবং-শিক্ষক" aria-label="Permalink to &quot;4. শিক্ষা প্রতিষ্ঠান এবং শিক্ষক&quot;">​</a></h2><ul><li><strong>পাবলিক শিক্ষা প্রতিষ্ঠান</strong>: রাষ্ট্র বা সভ্যতার সম্প্রদায় দ্বারা প্রতিষ্ঠিত, বিনামূল্যে মৌলিক শিক্ষা এবং পাবলিক শিক্ষা সেবা বহন করে, এবং তহবিল পাবলিক সঞ্চয় দ্বারা নিশ্চিত করা হয়।</li><li><strong>প্রাইভেট শিক্ষা প্রতিষ্ঠান</strong>: সামাজিক শক্তি দ্বারা আইন অনুযায়ী প্রতিষ্ঠিত, যুক্তিসঙ্গত ফি আদায় করতে পারে, কিন্তু অবশ্যই শিক্ষা অধিদপ্তরের তদারকি গ্রহণ করতে হবে, এবং মিথ্যা প্রচার এবং লুঠেরা ফি আদায় করতে পারবে না।</li><li><strong>সাধনা ধর্মীয় সংস্থা</strong>: ঐতিহ্যবাহী সাধনা সংস্থা নিবন্ধনের পরে পেশাদার শিক্ষা প্রতিষ্ঠান হিসেবে কার্যক্রম চালাতে পারে, এবং অবশ্যই শিক্ষা আইনের বিধান মেনে চলতে হবে, এবং সাধনা সম্পদ বন্ধ করে একচেটিয়া করতে পারবে না।</li><li><strong>শিক্ষকের অধিকার এবং কর্তব্য</strong>: শিক্ষক একাডেমিক স্বাধীনতা, যুক্তিসঙ্গত পারিশ্রমিক, পেশাদার প্রশিক্ষণ ইত্যাদি অধিকার উপভোগ করে, এবং একই সাথে শিক্ষাদান, আদর্শ ব্যক্তিত্ব, ছাত্রের গোপনীয়তা রক্ষা ইত্যাদি কর্তব্য পালন করে।</li></ul><h2 id="_5-শিক্ষা-বিষয়বস্তু-এবং-পাঠ্যক্রম-মানদণ্ড" tabindex="-1">5. শিক্ষা বিষয়বস্তু এবং পাঠ্যক্রম মানদণ্ড <a class="header-anchor" href="#_5-শিক্ষা-বিষয়বস্তু-এবং-পাঠ্যক্রম-মানদণ্ড" aria-label="Permalink to &quot;5. শিক্ষা বিষয়বস্তু এবং পাঠ্যক্রম মানদণ্ড&quot;">​</a></h2><p>শিক্ষা বিষয়বস্তু অবশ্যই নিম্নলিখিত প্রয়োজনীয়তা পূরণ করতে হবে:</p><ol><li>সিম্বায়োসিস সভ্যতার মূল দর্শন এবং লুঠেরা বিরোধী শিক্ষা অন্তর্ভুক্ত, এবং শিক্ষার্থীদের সিম্বায়োসিস চেতনা গড়ে তোলা।</li><li>তিনশত সেট মূল সাধনা ব্যবস্থার মৌলিক তত্ত্ব এবং প্রবেশ পদ্ধতি অন্তর্ভুক্ত।</li><li>মহাবিশ্বের নিয়ম,位面 জ্ঞান, জীবন বিজ্ঞান ইত্যাদি সাধারণ বৈজ্ঞানিক জ্ঞান অন্তর্ভুক্ত।</li><li>সকল প্রজাতির ইতিহাস এবং সংস্কৃতি অন্তর্ভুক্ত, এবং প্রজাতিগুলোর পারস্পরিক বোঝাপড়া এবং সম্মানকে প্রচার করা।</li><li>বাস্তব সাধনা এবং সামাজিক সেবার অংশ অন্তর্ভুক্ত, এবং জ্ঞান এবং কর্ম একীভূত করার ক্ষমতা গড়ে তোলা।</li><li>লুঠেরা সাধনা দর্শন এবং বৈষম্যমূলক চিন্তা প্রচার নিষিদ্ধ।</li></ol><h2 id="_6-আইনি-দায়বদ্ধতা" tabindex="-1">6. আইনি দায়বদ্ধতা <a class="header-anchor" href="#_6-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;6. আইনি দায়বদ্ধতা&quot;">​</a></h2><p>এই আইনের বিধান লঙ্ঘন করা কার্যক্রম, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ul><li>বয়সোত্পন্ন জীবকে বাধ্যতামূলক শিক্ষা গ্রহণ করতে অস্বীকার বা বাধা দেওয়া, সংশোধন করার নির্দেশ এবং শাস্তি।</li><li>শিক্ষা প্রতিষ্ঠানের বিধি বিরোধী ফি আদায়, মিথ্যা প্রচার, ফি ফেরত দেওয়ার নির্দেশ এবং জরিমানা, গুরুতর অপরাধের ক্ষেত্রে শিক্ষা প্রতিষ্ঠানের লাইসেন্স বাতিল।</li><li>শিক্ষকের শারীরিক শাস্তি বা ছাত্রের প্রতি বৈষম্য, শাস্তি, গুরুতর অপরাধের ক্ষেত্রে শিক্ষকের যোগ্যতা বাতিল এবং আইনি দায়বদ্ধতা আরোপ।</li><li>পাবলিক সাধনা সম্পদকে ব্যক্তিগত সম্পত্তি হিসেবে দখল করা, একচেটিয়া ফি আদায়, অবৈধ আয় জব্দ এবং জরিমানা।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《শিক্ষা নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার &quot;প্রত্যেকের পথ&quot; দর্শনের শিক্ষা অনুশীলন। এটি শিক্ষা অধিকার নিশ্চিত করা, স্তরবিন্যাস শিক্ষা ব্যবস্থা গঠন করা, সাধনা সম্পদ উন্মুক্ত করার মাধ্যমে, নিশ্চিত করে যে প্রতিটি জীব নিজের জন্য উপযুক্ত বিবর্তনের পথ পেতে পারে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য ক্রমাগত জ্ঞান এবং মানব সম্পদ সরবরাহ করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>37-共生教育体系 (সিম্বায়োসিস শিক্ষা ব্যবস্থা)</li><li>10-三百套本源修炼体系总览 (তিনশত সেট মূল সাধনা ব্যবস্থার সংক্ষিপ্ত বিবরণ)</li><li>08-人人有路保障体系 (প্রত্যেকের পথ নিশ্চয়তা ব্যবস্থা)</li></ul>',25)])])}const c=a(e,[["render",i]]);export{u as __pageData,c as default};
